    'SubMode_Supported_Customer' => __('When supported, the customer\'s saved payment method is charged automatically on each renewal due date.', 'fluent-cart'),
    'SubRpt_Average_Cohort' => __('The average cohort: the share of its customers still subscribed after each period, weighted by cohort size.', 'fluent-cart'),
    'SubRpt_Average_Cohort_Share' => __('The average cohort: the share of its starting MRR still coming in after each period, weighted by cohort size. It passes 100% when customers upgrade.', 'fluent-cart'),
    'SubRpt_Average_Revenue' => __('Average revenue per paying subscription: MRR divided by the subscriptions that pay more than 0. A discounted first year paid at 0 is left out.', 'fluent-cart'),
    'SubRpt_Canceled_Subscriptions' => __('Canceled subscriptions still in their paid term that end inside the horizon: the renewals they would have paid, unless the customer comes back.', 'fluent-cart'),
    /* translators: %1$s - date and time the cohort data was last generated */
    'SubRpt_Cohort_Data' => __('Cohort data was last generated on %1$s. Generate it again to include the latest subscriptions.', 'fluent-cart'),
    'SubRpt_Compare_Installment' => __('Compare installment prices by plans started, money collected, payments still scheduled and plans that lapse.', 'fluent-cart'),
    'SubRpt_Completed_Plans' => __('Completed plans out of plans that have ended (completed, lapsed or refunded). Running and overdue plans are left out.', 'fluent-cart'),
    'SubRpt_Customer_Whose' => __('A customer whose subscription ended and who bought the same product again within 30 days of its paid term end counts as kept the whole time, not as one who left and came back. Use it when customers cancel and rebuy to get a new-customer price.', 'fluent-cart'),
    'SubRpt_Every_Renewal' => __('Every renewal due in the horizon, if every customer renews. Canceled subscriptions are not included.', 'fluent-cart'),
    'SubRpt_Full_Month' => __('No full month in this range yet. Pick a range that covers at least one past month.', 'fluent-cart'),
    'SubRpt_Full_Year' => __('No full year in this range yet. Pick a range that covers at least one past year.', 'fluent-cart'),
    'SubRpt_Ideal_Amount' => __('The ideal amount less the projected one: what you are not expected to collect at these rates, the room a win-back or dunning effort has.', 'fluent-cart'),
    'SubRpt_Ideal_Amount_Renewal' => __('The ideal amount at the renewal rates below. They start at your store\'s own rates from the last 12 closed months; move the sliders to try other rates.', 'fluent-cart'),
    /* translators: %1$s - churned subscriptions that also started in this period */
    'SubRpt_Includes_Started' => __('Includes %1$s that started and ended in this period; the Retention page leaves these out.', 'fluent-cart'),
    'SubRpt_Monthly_Recurring' => __('Monthly recurring revenue now: active subscriptions at their renewal price, plus discounted first years at the price paid now, plus canceled subscriptions until their paid term ends. Installment plans, trials, failing and paused subscriptions are not included. The date range does not apply.', 'fluent-cart'),
    'SubRpt_Monthly_Recurring_Revenue' => __('Of the monthly recurring revenue at the start of the period, the share kept at its end. New subscriptions are not counted.', 'fluent-cart'),
    /* translators: %1$s: number of subscriptions */
    'SubRpt_Mrr_Canceled' => __('MRR of canceled subscriptions still in their paid term. In MRR until the term ends; it leaves then unless the customer comes back. Subscriptions: %1$s.', 'fluent-cart'),
    'SubRpt_Mrr_New' => __('MRR of new subscriptions less MRR of churned ones, plus plan upgrades less downgrades. An upgrade is no churn and no new subscription.', 'fluent-cart'),
    /* translators: %1$s: number of subscriptions */
    'SubRpt_Mrr_Subscriptions' => __('MRR from subscriptions in a discounted first cycle, at the price paid now. Subscriptions: %1$s.', 'fluent-cart'),
    /* translators: %1$s: number of subscriptions */
    'SubRpt_Mrr_Subscriptions_Whose' => __('MRR of subscriptions whose renewal payment failed. Not in MRR. Subscriptions: %1$s.', 'fluent-cart'),
    'SubRpt_New_Subscriptions' => __('New subscriptions and churned ones per period, and the net change. In MRR, plan upgrades and downgrades too. Installment plans are not included.', 'fluent-cart'),
    'SubRpt_Paid_Started' => __('Paid on started plans, net of refunds. When an order holds a plan and other items, the plan\'s share of that order\'s tax, shipping and refunds is estimated by line amount.', 'fluent-cart'),
    'SubRpt_Paid_Subscription' => __('Paid subscription renewals in this period. Installment payments are not counted.', 'fluent-cart'),
    'SubRpt_Payments_Left' => __('Payments left on active and overdue plans. Projected applies the collection rate.', 'fluent-cart'),
    'SubRpt_Plan_Ended' => __('No plan has ended yet, so the rate starts at 100%. Move the slider to try other rates.', 'fluent-cart'),
