    'SubRpt_Recurring_Subscriptions' => __('Recurring subscriptions that ended in this period: canceled, expired, failing, past due or paused. The same rule as the Retention page.', 'fluent-cart'),
    'SubRpt_Recurring_Subscriptions_Started' => __('Recurring subscriptions started in this period. A free trial counts when it first pays.', 'fluent-cart'),
