    'SubRpt_Renewals_Already' => __('Renewals already due and not paid: in payment retry (failing or past due), or overdue. Not in the forecast; they may still come in.', 'fluent-cart'),
    'SubRpt_Renewals_Fell' => __('Of the renewals that fell due in the period, the share that was paid. A plan canceled early counts as a lost renewal when its paid term ends. Renewals still retrying payment count once they settle.', 'fluent-cart'),
    /* translators: %1$s - the store timezone note */
    'SubRpt_Renewals_Scheduled' => __('Renewals scheduled by your live recurring subscriptions in the horizon, at their renewal price, by the month they fall due. Installment plans are not included; see the Installments report. %1$s', 'fluent-cart'),
    'SubRpt_Retention_Compares' => __('Retention compares the subscriptions active when a period began with those still active at its end. New subscriptions are not counted. Installment plans are not included.', 'fluent-cart'),
    'SubRpt_Row_Customers' => __('Each row is the customers who first paid in that month or year. Each column shows how many of them still had a running subscription after that many months or years. A customer who leaves and comes back counts again. Installment plans are not included.', 'fluent-cart'),
    'SubRpt_Scheduled_Overdue' => __('Scheduled and overdue payments at the collection rate set on the Monthly Schedule.', 'fluent-cart'),
