    /* translators: %1$s: home country name (e.g. Cyprus) */
    'Tax_Collecting_Cross' => __('Collecting cross-border EU VAT at your %1$s home country rate. This is for small businesses whose total cross-border EU sales stay below €10,000/year. Once you exceed that threshold you must charge each buyer\'s local VAT rate instead.', 'fluent-cart'),
    /* translators: %1$s: home country name (e.g. Germany) */
