    'Tax_Haven_Added' => __('You haven\'t added a home country registration. The information you add here will be used to create one for you.', 'fluent-cart'),
    /* translators: %1$s: home country name (e.g. Cyprus) */
    'Tax_Home_Country' => __('Your %1$s home country VAT rate will apply to all EU cross-border sales. This is available for small businesses below €10,000/year in cross-border EU sales. Make sure %1$s is registered below with the correct rate.', 'fluent-cart'),
    /* translators: %1$s: home country name (e.g. Germany) */
