    'Tax_Listed_Price' => __('Listed price stays unchanged on reverse charge. Only the tax line is zeroed on the invoice.', 'fluent-cart'),
    'Tax_Make_Sure' => __('Make sure you\'ve downloaded and saved the CSV file for your records before proceeding.', 'fluent-cart'),
    'Tax_Overwrite_Destination' => __('This will overwrite all EU destination country standard rates with preset defaults. Continue?', 'fluent-cart'),
    /* translators: %1$s: tax class name (e.g. Reduced) */
    'Tax_Permanently_Delete' => __('This will permanently delete the "%1$s" tax class and all its rates across every country (not just EU). Products using this class will fall back to Standard. Continue?', 'fluent-cart'),
    'Tax_Rates_Class' => __('All rates for this class will be deleted. Products using it will default to Standard.', 'fluent-cart'),
    'Tax_Rates_Pre' => __('Rates are pre-filled for convenience and may not reflect current laws — verify with a tax advisor before going live. If you sell products taxed at different rates (e.g. food, books, digital goods), use the + button to add tax classes.', 'fluent-cart'),
    'Tax_Register_Country' => __('Register in each EU country where you are required to collect VAT. Manage your registrations in the country list below.', 'fluent-cart'),
    'Tax_Set_Oss' => __('Set up OSS, micro-business, or specific-country registrations to collect VAT across the EU.', 'fluent-cart'),
